window.docContents[18].resolve({"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Exercises-with-Inductive-Relations--More-Facts-about--Le--Facts-about--_LT_--and--___":{"contents":"\n\nThe \"strictly less than\" relation n < m can now be defined\nin terms of Le.def Lt (n m : Nat) : Prop := Le (n + 1) m\n\nscoped infix:50 (priority := high) \" < \" => Lt\nThe ≥ relation is defined in terms of ≤, so unfolding its\ndefinition with rw lets us move between them.def Ge (m n : Nat) : Prop := Le n m\n\nscoped infix:50 (priority := high) \" ≥ \" => Ge\n\nexample (m n : Nat) (h : m ≥ n) : n ≤ m := by\n  rw [Ge] at h\n  assumption\ntheorem lt_not_lt_zero (n : Nat) : ¬ n < 0 := by\n  intro h\n  inversion h\ntheorem lt_or_ge (n m : Nat) : n < m ∨ n ≥ m := by\n  solution!\n    induction n generalizing m with\n    | zero =>\n      cases m with\n      | zero => right; constructor\n      | succ _ =>\n        left;\n        apply succ_le_succ;\n        apply zero_le\n    | succ n' ih =>\n      cases m with\n      | zero =>\n        rw [Ge]; right\n        apply zero_le\n      | succ m' =>\n        cases ih m' with\n        | inl ih =>\n          left\n          apply succ_le_succ\n          exact ih\n        | inr ih =>\n          right\n          apply succ_le_succ\n          exact ih\ntheorem le_of_lt (n m : Nat) (h : n < m) : n ≤ m := by\n  solution!\n    apply le_of_succ_le_succ\n    constructor; assumption\ntheorem lt_and_lt_of_add_lt (n₁ n₂ m : Nat) (h : n₁ + n₂ < m) : n₁ < m ∧ n₂ < m := by\n  solution!\n    constructor\n    · apply le_trans (n := (n₁ + n₂) + 1)\n      · apply succ_le_succ\n        apply le_add_right\n      · exact h\n    · apply le_trans (n := (n₂ + n₁) + 1)\n      · apply succ_le_succ\n        apply le_add_right\n      · rw [Nat.add_comm n₂]; assumption\n\n\n","context":"Logical Foundations\u0009IndProp: Inductively Defined Propositions\u0009Exercises with Inductive Relations\u0009More Facts about  Le","header":"9.3.1.2. Facts about  <  and  ≥","id":"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Exercises-with-Inductive-Relations--More-Facts-about--Le--Facts-about--_LT_--and--___"}});